-- Study Abroad country content, BATCH 25: Afghanistan, Iraq, Libya, Palestine, Myanmar, Laos, North Korea, Tajikistan, Turkmenistan.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('afghanistan', 'iraq', 'libya', 'palestine', 'myanmar', 'laos', 'north-korea', 'tajikistan', 'turkmenistan'));
UPDATE countries SET why_title = 'Why study in Afghanistan?', why_body = '<p>Afghanistan has public universities in Kabul, Herat and other cities, but conditions for international study are very restricted.<ul><li>Public universities such as Kabul University and Kabul Polytechnic</li><li>Pashto, Dari and some English instruction</li><li>Limited information for international students</li></ul></p><p>Check your own government''s travel advice before considering study in Afghanistan; this page is informational only.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No official student-visa guidance for studying in Afghanistan was found. A third-party summary of the Foreign Ministry criteria says the receiving Afghan university must be recognised; verify this directly.</p><ul><li>Admission letter from a recognised university</li><li>Check with the Afghan diplomatic mission and your government''s travel advice</li><li>Separately, the UK has paused new student visas for Afghan nationals applying from outside the UK from 26 March 2026</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Afghan diplomatic missions and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No official admission information was found; contact the universities directly.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance exam or interview where required</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No tuition figures were found.</p><ul><li>Contact the universities directly for fees</li><li>Living costs: not estimated because of conditions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Dari, Pashto or English proof depending on programme</li></ul>' WHERE slug = 'afghanistan';
UPDATE countries SET why_title = 'Why study in Iraq?', why_body = '<p>Iraq offers government-funded "Study in Iraq" scholarships for international students at public universities, with Arabic-taught degrees and growing English programmes.<ul><li>Study in Iraq scholarship programme</li><li>Established public universities in Baghdad, Mosul and Basrah</li><li>Low living costs</li><li>Rich history</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Students receive a <strong>student entry visa</strong> through the university with the Residency Affairs Directorate (Ministry of Interior), then a residence card after arrival. One guide estimates 6-10 weeks for the full process.</p><ul><li>Admission or scholarship acceptance letter</li><li>Application forwarded by the university to the Residency Affairs Directorate</li><li>Full scholarships cover tuition, visa and residency fees, housing and health insurance (programme announcements)</li><li>Requirements vary by nationality and programme</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Iraqi Ministry of Higher Education, Residency Affairs and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>The Study in Iraq portal (studyiniraq.scrd-gate.gov.iq) takes applications; the 2026/27 round is the fourth cycle, with undergraduate applications open until September 2026 and postgraduate closed in July 2026.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance exam or interview where required</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Scholarships can remove most costs.</p><ul><li>Study in Iraq full scholarships: tuition, visa and residency fees, housing and health insurance</li><li>Partial scholarships: 50% of tuition</li><li>No University of Baghdad fee schedule was found</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic or English proof depending on programme</li></ul>' WHERE slug = 'iraq';
UPDATE countries SET why_title = 'Why study in Libya?', why_body = '<p>Libya has public universities in Tripoli, Benghazi and Misrata, but security conditions are very severe and study is not currently advisable.<ul><li>Public universities with low tuition</li><li>Arabic-medium teaching</li><li>Limited international programmes</li></ul></p><p>Official governments advise against travel to Libya. This page is informational only and does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is required and must be applied for at the Libyan embassy in your country of residence; mail-in applications are not accepted (Canadian advice).</p><ul><li>Admission letter from a Libyan institution</li><li>Visa difficulty depends on the political climate</li><li>Canada advises avoiding all travel and the US lists Do Not Travel (issued 31 August 2026)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Libyan embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No official admission information was found; contact the universities directly.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance exam or interview where required</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities are state-funded with low tuition.</p><ul><li>No international tuition figures found</li><li>Living costs: not estimated because of conditions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic or English proof depending on programme</li></ul>' WHERE slug = 'libya';
UPDATE countries SET why_title = 'Why study in Palestine?', why_body = '<p>Palestine has Arabic- and English-taught universities such as An-Najah, Birzeit and Al-Quds, with strong Arabic-studies and exchange programmes.<ul><li>Universities such as An-Najah and Birzeit</li><li>Palestine and Arabic Studies programme at Birzeit</li><li>Exchange programmes for partner-university students</li><li>Check current conditions before planning</li></ul></p><p>Check your government''s travel advice and each university''s current status before planning.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>After the admission confirmation letter you can start obtaining the visa and travel documents (An-Najah). No official current visa rules for foreign students entering the West Bank were found, and Israeli restrictions can affect entry.</p><ul><li>Admission confirmation letter</li><li>Travel documents and visa as advised by the university</li><li>Contact An-Najah''s international office or Birzeit''s external relations office for current rules</li><li>Check your government''s travel advice</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official The universities'' international offices and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Exchange students from partner universities can study for one semester at Birzeit.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance exam or interview where required</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition is published in Jordanian dinars.</p><ul><li>An-Najah: fees in JOD (1 JOD is about US$1.4); see its fee schedule</li><li>Birzeit MSc in Urban Planning: about JOD 2,312 a year (third-party listing; confirm)</li><li>Birzeit exchange students may get a tuition waiver under cooperation agreements (not for the Palestine Arabic Studies Program)</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (Tawjihi or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Arabic or English proof depending on programme</li></ul>' WHERE slug = 'palestine';
UPDATE countries SET why_title = 'Why study in Myanmar?', why_body = '<p>Myanmar has public universities in Yangon and Mandalay, but conditions are difficult and most international students go elsewhere.<ul><li>Universities such as the University of Yangon and Mandalay University</li><li>Some English-medium programmes (for example at ITBMU)</li><li>Check current conditions before planning</li></ul></p><p>Check your government''s travel advice before considering study in Myanmar; this page is informational only.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Study requires an <strong>Education Visa</strong> from a Myanmar embassy (secondary guide). Official sources were not checked in detail.</p><ul><li>Admission letter from a Myanmar institution</li><li>Education Visa from a Myanmar embassy or consulate</li><li>A secondary guide cites UK advice against travel to many regions and Canadian advice against travel to the whole country (October 2026); confirm on official pages</li><li>Separately, the UK has paused new student visas for Myanmar nationals from 26 March 2026</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Myanmar embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance exam or interview where required</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No tuition figures were found.</p><ul><li>Contact the universities directly for fees</li><li>Living costs: about US$200-$400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English or Burmese proof depending on programme</li></ul>' WHERE slug = 'myanmar';
UPDATE countries SET why_title = 'Why study in Laos?', why_body = '<p>Laos offers degrees at the National University of Laos in Vientiane and regional universities, with low living costs in a small Southeast Asian country.<ul><li>National University of Laos</li><li>Low living costs</li><li>Lao-language and some English programmes</li><li>Mekong and cultural landscape</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Contact the Lao embassy and NUOL''s International Relations Office for current student-visa rules; no official 2026 visa information was found.</p><ul><li>Admission letter from a Lao institution</li><li>Student visa or entry permit per the embassy</li><li>Passport and proof of funds</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Lao embassy and NUOL International Relations Office site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>NUOL held 2026-27 entrance exams from 8 August 2026 (7,867 candidates), with separate exams for international and continuing-education programmes.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance exam or interview where required</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No international tuition schedule was found.</p><ul><li>Ask NUOL for international fees</li><li>Scholarship listings on aggregators are unreliable; check each provider</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Lao or English proof depending on programme</li></ul>' WHERE slug = 'laos';
UPDATE countries SET why_title = 'Why study in North Korea?', why_body = '<p>North Korea''s foreign-student programmes are small and state-controlled, mainly Korean-language courses at Kim Il Sung University in Pyongyang.<ul><li>Kim Il Sung University foreign-student programme dating from 1955</li><li>Mostly four-year Korean-language courses</li><li>Strict state control</li><li>Very limited public information</li></ul></p><p>Official governments strongly restrict travel to North Korea. This page is informational only and does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No public application procedure or fees are published; ask the university or the DPRK embassy. Foreigners in Pyongyang usually need permission to travel outside the city.</p><ul><li>Contact the DPRK embassy for any procedure</li><li>Foreign students live in a dormitory in Pyongyang</li><li>Reports describe host students who monitor foreign students'' activities</li><li>Check your government''s travel advice (the UK advises against all but essential travel, per a guide; US passports are not valid for travel unless specially validated)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DPRK embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No application procedure is published.</p><ul><li>Contact the university through official channels</li><li>Passport and official documents as required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs are unpublished.</p><ul><li>Get the full cost in writing before travelling</li><li>Living costs: unknown</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Korean language proof where required</li></ul>' WHERE slug = 'north-korea';
UPDATE countries SET why_title = 'Why study in Tajikistan?', why_body = '<p>Tajikistan offers low-cost degrees in Russian and Tajik, with medicine popular among international students and English-medium programmes at the University of Central Asia in Khorog.<ul><li>Low tuition and living costs</li><li>Medical universities such as Avicenna Tajik State Medical University</li><li>English-medium programmes at UCA</li><li>Pamir mountains</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Most sources say international students need a <strong>student visa</strong> for programmes longer than 45 days, usually arranged through the university after an admission letter. Educational visa type O1 covers university study.</p><ul><li>Admission letter from the university</li><li>Student visa from a Tajik embassy or consulate; the university visa office handles registration and extensions</li><li>Gorno-Badakhshan (Khorog) requires a separate permit</li><li>Work rights for students are unclear; no official page was found</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Tajik embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Places are filled through a state quota under intergovernmental agreements or paid contracts; the 2026/27 application window at Avicenna Tajik State Medical University ran 1-20 August 2026.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance exam or interview where required</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Estimates vary widely across guides.</p><ul><li>TNU tuition is set in each student''s contract</li><li>Guides: about US$1,200-$3,500 a year; others US$1,500-$7,000; public universities TJS 2,000-8,000</li><li>Medical programmes: about US$2,500-$4,500 a year (guides)</li><li>UCA Khorog: about US$2,500-$4,000 a year (aggregators)</li><li>Living costs: about US$150-$300 a month (guides)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Russian, Tajik or English proof depending on programme</li></ul>' WHERE slug = 'tajikistan';
UPDATE countries SET why_title = 'Why study in Turkmenistan?', why_body = '<p>Turkmenistan has a small higher-education system with a few English-medium options and limited scholarships; information for international students is thin.<ul><li>Turkmen State Medical University</li><li>International University of Humanities and Development (English-medium programmes)</li><li>Bilateral scholarships with Turkey and other partners</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Official visa and admission information was not found; the guide says student visas do not allow employment and post-study work is restricted (unverified). Confirm with the Turkmen embassy.</p><ul><li>Admission letter from a Turkmen institution</li><li>Student visa from a Turkmen embassy</li><li>No official ministry guidance found</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Turkmen embassy and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance exam or interview where required</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No tuition figures were found.</p><ul><li>Contact the institutions for fees</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Turkmen, Russian or English proof depending on programme</li></ul>' WHERE slug = 'turkmenistan';
COMMIT;
